    def test_typed_blob_roundtrip(self):
        self.assertEqual(m.untyped(m.typed(b"\x00\xff")), b"\x00\xff")

    def test_typed_real_negative_zero_roundtrip(self):
        self.assertEqual(m.typed(m.untyped(m.typed(-0.0))), m.typed(-0.0))
        self.assertNotEqual(m.typed(0.0), m.typed(-0.0))

    def test_typed_integer_float_distinct(self):
        self.assertNotEqual(m.typed(1), m.typed(1.0))

    def test_typed_bool_refused(self):
        with self.assertRaises(m.Held):
            m.typed(True)

    def test_typed_nonfinite_refused(self):
        for x in (float("nan"), float("inf")):
            with self.assertRaises(m.Held):
                m.typed(x)

    def test_noncanonical_blob_refused(self):
        with self.assertRaises(m.Held):
            m.untyped(["blob", "not-base64"])

    def test_last_snapshot_callback_cannot_hide_reference_change(self):
        real = m.snapshot
        calls = []

        def changed(conn, *args, **kwargs):
            result = real(conn, *args, **kwargs)
            calls.append(True)
            if len(calls) == 4:
                conn.execute(
                    "UPDATE READ_PROGRESS SET locator=x'aa' WHERE BOOK_ID='wrong-0'"
                )
                conn.commit()
            return result

        with (
            patch.object(m, "snapshot", side_effect=changed),
            self.assertRaisesRegex(m.Held, "terminal-fixture-table-drift"),
        ):
            self.run_fixture()
        self.assertEqual(len(calls), 4)


